import java.io.*;
public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int k = Integer.parseInt(firstLine[1]);
        int[] v = new int[10];
        String[] keys = br.readLine().split(" ");
        for (String key : keys) {
            int x = Integer.parseInt(key);
            v[x] = 1;
        }
        int[] ans = {1};
        int p = n / 2;
        while (true) {
            if (p % 2 != 0) {
                ans = multiplyMod(ans, v, 998244353);
            }
            p /= 2;
            if (p == 0) break;
            v = multiplyMod(v, v, 998244353);
        }
        int res = 0;
        for (int x : ans) {
            res = (res + x * x) % 998244353;
        }
        pw.println(res);
        pw.flush();
    }

    static int[] multiplyMod(int[] a, int[] b, int mod) {
        int need = a.length + b.length - 1;
        int n = Math.max(2, Integer.highestOneBit(need - 1) << 1);
        double[] aReal = new double[n];
        double[] aImaginary = new double[n];
        for (int i = 0; i < a.length; i++) {
            int x = ((a[i] % mod) + mod) % mod;
            aReal[i] = x & ((1 << 15) - 1);
            aImaginary[i] = x >> 15;
        }
        fft(aReal, aImaginary, false);
        double[] bReal = new double[n];
        double[] bImaginary = new double[n];
        if (a == b) {
            System.arraycopy(aReal, 0, bReal, 0, n);
            System.arraycopy(aImaginary, 0, bImaginary, 0, n);
        } else {
            for (int i = 0; i < b.length; i++) {
                int x = ((b[i] % mod) + mod) % mod;
                bReal[i] = x & ((1 << 15) - 1);
                bImaginary[i] = x >> 15;
            }
            fft(bReal, bImaginary, false);
        }
        double[] faReal = new double[n];
        double[] faImaginary = new double[n];
        double[] fbReal = new double[n];
        double[] fbImaginary = new double[n];

        double cf = 0.25 / n;
        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);

            double a1r = aReal[i] + aReal[j];
            double a1i = aImaginary[i] - aImaginary[j];
            double a2r = aImaginary[i] + aImaginary[j];
            double a2i = aReal[j] - aReal[i];

            double b1r = (bReal[i] + bReal[j]) * cf;
            double b1i = (bImaginary[i] - bImaginary[j]) * cf;
            double b2r = (bImaginary[i] + bImaginary[j]) * cf;
            double b2i = (bReal[j] - bReal[i]) * cf;

            faReal[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            faImaginary[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;

            fbReal[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            fbImaginary[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(faReal, faImaginary, true);
        fft(fbReal, fbImaginary, true);
        int[] res = new int[need];
        for (int i = 0; i < need; i++) {
            long aa = Math.round(faReal[i]);
            long bb = Math.round(fbReal[i]);
            long cc = Math.round(faImaginary[i]);
            res[i] = (int)((aa + (bb % mod) << 15) + ((cc % mod) << 30)) % mod;
        }
        return res;
    }

    static void fft(double[] a, double[] b, boolean inverse) {
        int n = a.length;
        int shift = 32 - Integer.numberOfTrailingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i << shift);
            if (i < j) {
                double tempA = a[i];
                a[i] = a[j];
                a[j] = tempA;
                double tempB = b[i];
                b[i] = b[j];
                b[j] = tempB;
            }
        }
        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosTable = new double[half];
            double[] sinTable = new double[half];
            for (int i = 0; i < half; i++) {
                double angle = 2 * Math.PI * i / len * (inverse ? -1 : 1);
                cosTable[i] = Math.cos(angle);
                sinTable[i] = Math.sin(angle);
            }
            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double wr = cosTable[j];
                    double wi = sinTable[j];
                    double uA = a[i + j];
                    double uB = b[i + j];
                    double vA = a[i + j + half] * wr - b[i + j + half] * wi;
                    double vB = a[i + j + half] * wi + b[i + j + half] * wr;
                    a[i + j] = uA + vA;
                    b[i + j] = uB + vB;
                    a[i + j + half] = uA - vA;
                    b[i + j + half] = uB - vB;
                }
            }
        }
        // scaling removed intentionally for inverse or not for clarity
    }
}
